CREATE TRIGGER driver_document_assignment BEFORE UPDATE OF driver_id ON trips WHEN NEW.driver_id IS NOT NULL AND (OLD.driver_id IS NULL OR NEW.driver_id<>OLD.driver_id) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM captain_applications a WHERE a.id=NEW.driver_id AND date(json_extract(a.vehicle_json,'$.identityExpiry'))>=date('now') AND date(json_extract(a.vehicle_json,'$.licenseExpiry'))>=date('now') AND date(json_extract(a.vehicle_json,'$.registrationExpiry'))>=date('now') AND date(json_extract(a.vehicle_json,'$.insuranceExpiry'))>=date('now')) THEN RAISE(ABORT,'DRIVER_DOCUMENT_EXPIRED') END; END;
